        if len(rows) >= 2:
            choices.append((max(rows) - min(rows), "v", c, min(rows), max(rows)))
    if choices:
        _, orient, fixed, lo, hi = max(choices)
        network = set()
        if orient == "h":
            network.update((fixed, c) for c in range(lo, hi + 1))
        else:
            network.update((r, fixed) for r in range(lo, hi + 1))
    else:
        # Use the median row and column as the initial rectilinear backbone.
        rs = sorted(r for r, c in pts)
        cs = sorted(c for r, c in pts)
        mr, mc = rs[len(rs)//2], cs[len(cs)//2]
        network = {(mr, c) for c in range(min(cs), max(cs)+1)}
